<?php
namespace App\Controllers\Admin;
use App\Core\{Auth,ConsoleView,Database,RateLimiter,RequestGuard,SecretStore,Settings,WebhookEngine};
final class WebhookConsoleController
{
    public function index(): void { Auth::requireAdmin(); $status=$_SESSION['hook_notice']??null; unset($_SESSION['hook_notice']);
        if ($_SERVER['REQUEST_METHOD']==='POST') { RequestGuard::post(); try { if (isset($_POST['action_test_webhook'])||($_POST['action']??'')==='test') { if (!RateLimiter::consume('hook-test:'.Auth::id(),3,300)) throw new \InvalidArgumentException('Espera antes de repetir el envío de prueba.'); $id=WebhookEngine::enqueue('test','Prueba manual solicitada desde la consola de Goldensite. No contiene datos de usuarios.',true); if (!$id) throw new \InvalidArgumentException('Activa el módulo, guarda un endpoint y habilita el despacho antes de probar.'); $result=WebhookEngine::deliver($id); $status=$result['state']==='delivered'?'El receptor confirmó el envío de prueba.':($result['state']==='retry'?'El receptor no confirmó. El intento quedó registrado y pendiente de reintento.':'La prueba falló. Consulta el estado del envío.'); }
            elseif (($_POST['action']??'')==='retry') { $id=ConsoleView::field($_POST,'delivery_id',32); Database::getInstance()->execute("UPDATE goldensite_webhook_deliveries SET state='pending',next_attempt_at=NULL WHERE id=? AND state='failed' AND attempts<5",[$id]); $status='Reintento preparado. El trabajador lo procesará.'; }
            else { $current=WebhookEngine::config(); $provider=ConsoleView::field($_POST,'provider',20)?:'discord'; $url=ConsoleView::field($_POST,'webhook_url',2000)?:ConsoleView::field($_POST,'discord_webhook_url',2000); if ($url==='') $url=$current['url']; $enabled=isset($_POST['webhook_enabled']); if ($url!=='') WebhookEngine::url($url,$provider); if ($enabled&&$url==='') throw new \InvalidArgumentException('Configura primero el endpoint.'); $events=$_POST['events']??[]; if (!is_array($events)||!array_is_list($events)||array_filter($events,static fn($v)=>!is_string($v))||array_diff($events,array_keys(WebhookEngine::EVENTS))) throw new \InvalidArgumentException('Eventos inválidos.'); $chat=ConsoleView::field($_POST,'chat_id',100); if ($provider==='telegram'&&!preg_match('/^(?:-?\d+|@[A-Za-z0-9_]{5,})$/D',$chat)) throw new \InvalidArgumentException('Configura el chat_id o canal de Telegram.'); $secret=ConsoleView::field($_POST,'signing_secret',255); $sameEndpoint=$provider===$current['provider']&&$url===$current['url']; $effectiveSecret=$secret!==''?$secret:($sameEndpoint?$current['secret']:''); if ($enabled&&$provider==='json'&&strlen($effectiveSecret)<32) throw new \InvalidArgumentException('El webhook JSON requiere un secreto de firma de al menos 32 caracteres.'); Settings::writeMany(['hooks_enabled'=>$enabled?'1':'0','hooks_provider'=>$provider,'hooks_url'=>SecretStore::seal($url),'hooks_events'=>json_encode($events,JSON_THROW_ON_ERROR),'hooks_chat'=>$chat,'hooks_secret'=>$secret!==''?SecretStore::seal($secret):($sameEndpoint?Settings::get('hooks_secret'):'')]); ConsoleView::audit('webhook_settings_updated'); $status='Configuración guardada. Los eventos seleccionados se registrarán en la cola.'; }
            $_SESSION['hook_notice']=$status; header('Location: /admin/webhooks'); return;
        } catch (\InvalidArgumentException $e) { http_response_code(422); $status=$e->getMessage(); } }
        $config=WebhookEngine::config(); $host=$config['url']?parse_url($config['url'],PHP_URL_HOST):''; unset($config['url'],$config['secret']);
        ConsoleView::render('webhooks',['config'=>$config,'host'=>$host,'status'=>$status,'deliveries'=>Database::getInstance()->fetchAll('SELECT id,event_name,state,attempts,http_code,duration_ms,last_error,created_at FROM goldensite_webhook_deliveries ORDER BY created_at DESC LIMIT 30')],'Webhooks · Goldensite');
    }
}
